for name, (anchor, addition) in additions.items():
    old = Path(name).read_text()
    assert old.count(anchor) == 1
    new = old.replace(anchor, addition + anchor)
    diff = ''.join(difflib.unified_diff(old.splitlines(True), new.splitlines(True), 'a/'+name, 'b/'+name))
    subprocess.run(['patch', '-p1'], input=diff, text=True, check=True)
